        return <PlaceholderPage title="Настройки" description="Параметры аккаунта и интеграции." />;
    }
  })();

  return (
    <div className="app">
      <Sidebar
        active={section}
        collapsed={collapsed}
        onNavigate={setSection}
        onToggle={() => setCollapsed((value) => !value)}
      />
      <main className="main">{page}</main>
    </div>
  );
}

