/* ---------- Оболочка: боковая панель + контент ---------- */

html,
body,
#root {
  height: 100%;
  margin: 0;
}

.app {
  display: flex;
  height: 100vh;
  background: var(--g-color-base-background);
  color: var(--g-color-text-primary);
}

.main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* ---------- Боковая навигация ---------- */

.sidebar {
  flex: 0 0 240px;
  width: 240px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  padding: 12px 8px;
  border-right: 1px solid var(--g-color-line-generic);
  background: var(--g-color-base-background);
  overflow: hidden;
  transition: width 0.2s ease, flex-basis 0.2s ease;
}

.sidebar--collapsed {
  flex-basis: 64px;
  width: 64px;
}

.sidebar__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 8px;
  margin-bottom: 12px;
  white-space: nowrap;
  font-weight: 600;
  font-size: 16px;
}

.sidebar--collapsed .sidebar__brand {
  justify-content: center;
  padding: 0;
}

.sidebar__logo {
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: var(--g-color-base-brand);
  color: #fff;
  font-weight: 700;
}

.sidebar__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sidebar__item,
.sidebar__toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 40px;
  box-sizing: border-box;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--g-color-text-secondary);
  font: inherit;
  font-size: 14px;
  text-align: left;
  white-space: nowrap;
  cursor: pointer;
}

.sidebar__item:hover,
.sidebar__toggle:hover {
  background: var(--g-color-base-simple-hover);
  color: var(--g-color-text-primary);
}

.sidebar__item[aria-current='page'] {
  background: var(--g-color-base-selection);
  color: var(--g-color-text-primary);
  font-weight: 600;
}

.sidebar__item:focus-visible,
.sidebar__toggle:focus-visible,
.sidebar__logo:focus-visible {
  outline: 2px solid var(--g-color-base-brand);
  outline-offset: 2px;
}

.sidebar__toggle {
  margin-top: auto;
}

/* В свёрнутом виде — только иконки по центру */
.sidebar--collapsed .sidebar__item,
.sidebar--collapsed .sidebar__toggle {
  justify-content: center;
  padding: 0;
  gap: 0;
}

/* ---------- Страницы ---------- */

.page {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 24px 28px;
  box-sizing: border-box;
  overflow: auto;
}

.page__header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.page__title {
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  line-height: 1.2;
}

.page__subtitle {
  margin: 0;
  color: var(--g-color-text-secondary);
  font-size: 14px;
}

.page__section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}

.page__section-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}

.page__fill {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* ---------- KPI-плитки ---------- */

.kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 16px;
}

.kpi {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px 20px;
  box-sizing: border-box;
}

.kpi__label {
  color: var(--g-color-text-secondary);
  font-size: 13px;
}

/* Крупное значение: пропорциональные цифры, без tabular-nums */
.kpi__value {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.1;
}

.kpi__delta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  font-weight: 500;
}

.kpi__delta--good {
  color: var(--g-color-text-positive);
}

.kpi__delta--bad {
  color: var(--g-color-text-danger);
}

.kpi__delta--neutral {
  color: var(--g-color-text-secondary);
}

.kpi__hint {
  color: var(--g-color-text-secondary);
  font-weight: 400;
}

