.orders {
  flex: 1 0 480px;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 12px;
  background: var(--g-color-base-background);
  overflow: hidden;
}

.orders__toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.orders__count {
  color: var(--g-color-text-secondary);
  font-size: 13px;
}

.orders__scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.orders-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 14px;
}

.orders-table th,
.orders-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--g-color-line-generic);
  text-align: left;
  white-space: nowrap;
  vertical-align: middle;
}

.orders-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--g-color-base-background);
  color: var(--g-color-text-secondary);
  font-size: 13px;
  font-weight: 500;
  user-select: none;
}

.orders-table th.is-draggable {
  cursor: grab;
}

.orders-table th.is-draggable:focus-visible {
  outline: 2px solid var(--g-color-base-brand);
  outline-offset: -2px;
}

.orders-table th.is-dragging {
  opacity: 0.45;
}

.orders-table th.drop-before {
  box-shadow: inset 2px 0 0 var(--g-color-base-brand);
}

.orders-table th.drop-after {
  box-shadow: inset -2px 0 0 var(--g-color-base-brand);
}

.th-content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.th-grip {
  opacity: 0.35;
}

.orders-table th:hover .th-grip {
  opacity: 0.8;
}

.align-end {
  text-align: right !important;
}

/* Колонки с числами выравниваем по цифрам */
.num {
  font-variant-numeric: tabular-nums;
}

.orders-table tbody {
  user-select: none;
}

.orders-table tbody tr {
  cursor: pointer;
}

.orders-table tbody tr:hover td {
  background: var(--g-color-base-simple-hover);
}

.orders-table tbody tr.is-selected td {
  background: var(--g-color-base-selection);
}

.orders-table tbody tr.is-selected:hover td {
  background: var(--g-color-base-selection-hover);
}

.cell-select,
.orders-table thead th.cell-select {
  width: 40px;
  padding-right: 0;
  cursor: default;
}

.select-box {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--g-color-base-brand);
  cursor: pointer;
}

.empty-row {
  padding: 32px;
  text-align: center;
  color: var(--g-color-text-secondary);
  cursor: default;
}

/* Строка-заголовок группы */
.orders-table tr.group-row td {
  padding: 0;
  background: var(--g-color-base-neutral-light);
  border-bottom: 1px solid var(--g-color-line-generic);
  cursor: default;
}

.group-row__content {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
}

.group-row__toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--g-color-text-primary);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.group-row__toggle:hover {
  background: var(--g-color-base-simple-hover);
}

.group-row__toggle:focus-visible {
  outline: 2px solid var(--g-color-base-brand);
  outline-offset: 1px;
}

.group-row__title {
  font-weight: 600;
}

.group-row__meta {
  color: var(--g-color-text-secondary);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

