import { chromium } from 'playwright';

const url = 'http://127.0.0.1:5180/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForSelector('.orders-table');
const headers = () => page.$$eval('.orders-table thead th', (ths) => ths.map((t) => t.textContent.trim()));
console.log('initial headers:', await headers());
console.log('rows on dashboard:', await page.locator('.orders-table tbody tr').count());
console.log('kpi:', await page.$$eval('.kpi', (els) => els.map((e) => e.innerText.replace(/\n+/g, ' | '))));
await page.screenshot({ path: '/tmp/pwcheck/01-dashboard.png' });

// Sidebar: collapse / expand
await page.click('.sidebar__toggle');
await page.waitForTimeout(300);
console.log('sidebar collapsed class:', await page.$eval('.sidebar', (e) => e.className), 'width:', await page.$eval('.sidebar', (e) => e.getBoundingClientRect().width));
await page.hover('.sidebar__item[aria-label="Заказы"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/pwcheck/02-collapsed.png' });
await page.click('.sidebar__toggle');
await page.waitForTimeout(300);

// Row selection: click, shift-click range, checkbox
const rows = page.locator('.orders-table tbody tr:not(.group-row)');
await rows.nth(0).click();
await rows.nth(3).click({ modifiers: ['Shift'] });
console.log('selected after click+shift-click (expect 4):', await page.locator('.orders-table tbody tr.is-selected').count());
await rows.nth(1).locator('td.cell-select').click(); // toggles off row 1
console.log('after toggling row 1 off (expect 3):', await page.locator('.orders-table tbody tr.is-selected').count());
await page.locator('.orders-table tbody tr:not(.group-row)').nth(1).locator('input.select-box').click();
console.log('after toggling row 1 via checkbox (expect 4):', await page.locator('.orders-table tbody tr.is-selected').count());
console.log('toolbar:', await page.locator('.orders__count').innerText());

// Column drag: move "Клиент" (index 1) onto "Сумма" (last)
await page.locator('.orders-table thead th', { hasText: 'Клиент' }).dragTo(page.locator('.orders-table thead th', { hasText: 'Сумма' }));
console.log('headers after drag:', await headers());

// Keyboard reorder: focus "Дата", Alt+ArrowRight
await page.locator('.orders-table thead th', { hasText: 'Дата' }).focus();
await page.keyboard.press('Alt+ArrowRight');
console.log('headers after Alt+Right on Дата:', await headers());
console.log('focused header:', await page.evaluate(() => document.activeElement?.textContent?.trim()));

// Grouping by status
await page.locator('.orders__toolbar .g-select, .orders__toolbar button').first().click();
await page.getByText('По статусу', { exact: true }).click();
await page.waitForTimeout(200);
console.log('group headers:', await page.$$eval('.group-row__title', (els) => els.map((e) => e.textContent)));
await page.screenshot({ path: '/tmp/pwcheck/03-grouped.png' });

// Collapse first group
await page.locator('.group-row__toggle').first().click();
console.log('rows after collapsing first group:', await rows.count());
await page.locator('.group-row__toggle').first().click();

// Group select-all checkbox
await page.locator('.group-row .select-box').nth(1).click();
console.log('selected after group select:', await page.locator('.orders-table tbody tr.is-selected').count());
console.log('errors:', errors);

// Orders page
await page.click('.sidebar__item[aria-label="Заказы"]');
await page.waitForSelector('.orders-table');
await page.screenshot({ path: '/tmp/pwcheck/04-orders.png' });
console.log('orders page rows:', await page.locator('.orders-table tbody tr:not(.group-row)').count());
await page.click('.sidebar__item[aria-label="Настройки"]');
await page.waitForTimeout(100);
console.log('settings title:', await page.locator('.page__title').innerText());
console.log('final errors:', errors);
await browser.close();

